function encodeWav24(samples, sampleRate){
  const n = samples.length, dataLen = n * 3;
  const buf = new ArrayBuffer(44 + dataLen); const v = new DataView(buf);
  const ws = (o,s) => { for(let i=0;i<s.length;i++) v.setUint8(o+i,s.charCodeAt(i)); };
  ws(0,"RIFF"); v.setUint32(4,36+dataLen,true); ws(8,"WAVE");
  ws(12,"fmt "); v.setUint32(16,16,true); v.setUint16(20,1,true); v.setUint16(22,1,true);
  v.setUint32(24,sampleRate,true); v.setUint32(28,sampleRate*3,true); v.setUint16(32,3,true); v.setUint16(34,24,true);
  ws(36,"data"); v.setUint32(40,dataLen,true);
  let o=44;
  for(let i=0;i<n;i++){ const s=Math.max(-1,Math.min(1,samples[i])); const x=Math.round(s*8388607);
    v.setUint8(o++,x&0xff); v.setUint8(o++,(x>>8)&0xff); v.setUint8(o++,(x>>16)&0xff); }
  return new Blob([buf],{type:"audio/wav"});
}

function getMicConstraints(){
  return { audio:{ echoCancellation:false, noiseSuppression:false, autoGainControl:false, channelCount:1 } };
}

async function checkMicProcessing(stream){
  const track=stream.getAudioTracks()[0];
  if(!track||!track.getSettings){ procStatus=null; return; }
  let s=track.getSettings();
  if(s.autoGainControl===true && track.applyConstraints){
    try{ await track.applyConstraints({autoGainControl:false}); s=track.getSettings(); }catch(e){}
  }
  // Capture-metadata provenance (D29): the track's reported sample rate + the
  // AudioContext rate, stamped onto mic_settings for the server's provenance verifier.
  // Best-effort — Safari/WebKit omit track.getSettings().sampleRate (→ null → the
  // verifier rests on the spectral verdict; null never blocks). Boundary rate is
  // corroboration only (the OS can resample pre-browser), not decisive.
  procStatus={ agc:s.autoGainControl, ns:s.noiseSuppression, ec:s.echoCancellation,
    track_sample_rate:(typeof s.sampleRate==='number'?s.sampleRate:null),
    context_sample_rate:(audioCtx&&audioCtx.sampleRate?audioCtx.sampleRate:null) };
  // Stamped here because this is the only place the RAW getSettings() object is in
  // scope — procStatus above flattens absent keys to undefined, which JSON drops, so
  // presence can no longer be told from present-and-false once it is copied.
  lastBrowserFingerprint=browserFingerprint(s);
}

function browserFingerprint(s){
  try{
    s=s||{};
    return { has_user_agent_data: !!(navigator.userAgentData),
             max_touch_points: (typeof navigator.maxTouchPoints==="number"?navigator.maxTouchPoints:null),
             reports_agc: ("autoGainControl" in s),
             reports_ns: ("noiseSuppression" in s),
             reports_sample_rate: (typeof s.sampleRate==="number") };
  }catch(e){ return {fingerprint_error:true}; }
}

const IS_MOBILE=(()=>{try{
  if(navigator.userAgentData&&typeof navigator.userAgentData.mobile==="boolean") return navigator.userAgentData.mobile;
  const ua=navigator.userAgent||"";
  // Mobile test FIRST — Android UAs also contain "Linux".
  if(/Android|iPhone|iPod|iPad|Mobile/i.test(ua)) return true;
  if(/Macintosh|Windows NT|X11|Linux|CrOS/i.test(ua)) return false;
  return null;
}catch(e){ return null; }})();

